namespace sv_355d88d45cca4626b8bdd9b631b6a03e.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_355d88d45cca4626b8bdd9b631b6a03e.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
                <span class="nav-icon">@GetIcon(section)</span>
                <span class="nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_355d88d45cca4626b8bdd9b631b6a03e.Components.Pages.Settings
@using sv_355d88d45cca4626b8bdd9b631b6a03e.Services

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (Profile is not null)
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <img src="@avatarUrl" alt="Avatar" class="avatar-image" />
                <div class="avatar-url-display">
                    <label>Avatar URL</label>
                    <input type="text" value="@avatarUrl" readonly class="form-input" />
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-input" @bind="displayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-input" @bind="email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-input form-textarea" @bind="bio" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveChanges">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
            </div>

            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="toast @statusClass">@statusMessage</div>
            }
        </div>
    }
    else
    {
        <p>Loading profile...</p>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string displayName = "";
    private string email = "";
    private string bio = "";
    private string avatarUrl = "";
    private string statusMessage = "";
    private string statusClass = "";

    protected override void OnParametersSet()
    {
        if (Profile is not null && string.IsNullOrEmpty(displayName))
        {
            ResetToProfile();
        }
    }

    private void ResetToProfile()
    {
        if (Profile is null) return;
        displayName = Profile.DisplayName;
        email = Profile.Email;
        bio = Profile.Bio;
        avatarUrl = Profile.AvatarUrl;
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(displayName, email, avatarUrl, bio);
        await OnSave.InvokeAsync(updated);
        statusMessage = "Profile saved successfully!";
        statusClass = "toast-success";
        StateHasChanged();
        _ = ClearMessageAfterDelay();
    }

    private void DiscardChanges()
    {
        ResetToProfile();
        statusMessage = "Changes discarded.";
        statusClass = "toast-info";
        StateHasChanged();
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        statusMessage = "";
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_355d88d45cca4626b8bdd9b631b6a03e.Components.Pages.Settings
@using sv_355d88d45cca4626b8bdd9b631b6a03e.Services

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (Prefs is not null)
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-item">
                    <span>Email Notifications</span>
                    <input type="checkbox" class="toggle-switch" @bind="emailNotifications" />
                </label>

                <label class="toggle-item">
                    <span>Push Notifications</span>
                    <input type="checkbox" class="toggle-switch" @bind="pushNotifications" />
                </label>

                <label class="toggle-item">
                    <span>Weekly Digest</span>
                    <input type="checkbox" class="toggle-switch" @bind="weeklyDigest" />
                </label>
            </div>

            <div class="muted-channels">
                <h3>Muted Channels</h3>
                @foreach (var channel in allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                        <span>@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SavePreferences">Save Preferences</button>
            </div>

            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="toast toast-success">@statusMessage</div>
            }
        </div>
    }
    else
    {
        <p>Loading notification preferences...</p>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }
    [Parameter] public List<string> AllChannels { get; set; } = new();

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = new();
    private string statusMessage = "";

    protected override void OnParametersSet()
    {
        allChannels = AllChannels.Count > 0 ? AllChannels : new List<string> { "general", "announcements", "updates", "marketing", "engineering" };

        if (Prefs is not null)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        statusMessage = "Preferences saved!";
        StateHasChanged();
        _ = ClearMessage();
    }

    private async Task ClearMessage()
    {
        await Task.Delay(3000);
        statusMessage = "";
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_355d88d45cca4626b8bdd9b631b6a03e.Components.Pages.Settings
@using sv_355d88d45cca4626b8bdd9b631b6a03e.Services

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (Settings is not null)
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
                <span>Change Password</span>
                <span class="panel-toggle">@(passwordPanelOpen ? "▼" : "▶")</span>
            </button>

            @if (passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" class="form-input" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" class="form-input" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" class="form-input" @bind="confirmPassword" />
                    </div>

                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="toast toast-error">@passwordError</div>
                    }
                    @if (!string.IsNullOrEmpty(passwordSuccess))
                    {
                        <div class="toast toast-success">@passwordSuccess</div>
                    }

                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="security-item">
            <div class="twofa-row">
                <div>
                    <h3>Two-Factor Authentication</h3>
                    <span class="status-indicator @(Settings.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                        @(Settings.TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                    </span>
                </div>
                <label class="toggle-item">
                    <input type="checkbox" class="toggle-switch" checked="@Settings.TwoFactorEnabled" disabled />
                </label>
            </div>
            @if (Settings.LastPasswordChange.HasValue)
            {
                <p class="last-change">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-session-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="dialog-overlay" @onclick="CancelRevoke">
                <div class="dialog" @onclick:stopPropagation="true">
                    <h3>Revoke Session</h3>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                    <div class="dialog-actions">
                        <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
    else
    {
        <p>Loading security settings...</p>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string passwordError = "";
    private string passwordSuccess = "";
    private ActiveSession? sessionToRevoke;

    private async Task UpdatePassword()
    {
        passwordError = "";
        passwordSuccess = "";

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
