@namespace sv_355d88d45cca4626b8bdd9b631b6a03e.Components.Pages.Settings
@using sv_355d88d45cca4626b8bdd9b631b6a03e.Services

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (Settings is not null)
    {
        <div class="appearance-form">
            <!-- Theme Selector -->
            <div class="form-group">
                <label><strong>Theme</strong></label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(selectedTheme == theme)"
                                   @onchange="() => selectedTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="form-group">
                <label><strong>Font Size</strong></label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(selectedFontSize == size)"
                                   @onchange="() => selectedFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="form-group">
                <label for="language"><strong>Language</strong></label>
                <select id="language" class="form-input" @bind="selectedLanguage">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="form-group">
                <label class="toggle-item">
                    <span><strong>Compact Mode</strong></span>
                    <input type="checkbox" class="toggle-switch" @bind="compactMode" />
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p class="preview-text">This is how your content will appear with the selected settings.</p>
                <div class="preview-card">
                    <span class="preview-label">Sample Card</span>
                    <p>The quick brown fox jumps over the lazy dog.</p>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>

            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="toast toast-success">@statusMessage</div>
            }
        </div>
    }
    else
    {
        <p>Loading appearance settings...</p>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;
    private string statusMessage = "";

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{selectedTheme.ToLower()} preview-font-{selectedFontSize.ToLower()}";
        if (compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
        statusMessage = "Appearance saved!";
        StateHasChanged();
        _ = ClearMessage();
    }

    private async Task ClearMessage()
    {
        await Task.Delay(3000);
        statusMessage = "";
        await InvokeAsync(StateHasChanged);
    }
}

