    background: var(--sidebar-bg, #f8f9fa);
    border-right: 1px solid var(--border-color, #dee2e6);
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.875rem 1.5rem;
    cursor: pointer;
    color: var(--text-muted, #6c757d);
    font-weight: 500;
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.settings-nav-item:hover {
    background: var(--hover-bg, #e9ecef);
    color: var(--text-color, #212529);
}

.settings-nav-item.active {
    background: var(--active-bg, #e7f1ff);
    color: var(--primary-color, #0d6efd);
    border-left-color: var(--primary-color, #0d6efd);
    font-weight: 600;
}

.nav-icon {
    font-size: 1.2rem;
}

/* Content Area */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
}

.settings-section h2 {
    margin: 0 0 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--heading-color, #212529);
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    color: var(--label-color, #495057);
}

.form-input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--border-color, #ced4da);
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s ease;
    box-sizing: border-box;
}

.form-input:focus {
    outline: none;
    border-color: var(--primary-color, #0d6efd);
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.1);
}

.form-textarea {
    resize: vertical;
    min-height: 80px;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.15s ease;
}

.btn-primary {
    background: var(--primary-color, #0d6efd);
    color: white;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: var(--secondary-bg, #e9ecef);
    color: var(--text-color, #495057);
}

.btn-secondary:hover {
    background: #dde0e3;
}

.btn-danger {
    background: #dc3545;
    color: white;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.25rem 0.625rem;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Toast Messages */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    animation: slideIn 0.2s ease;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-info {
    background: #cff4fc;
    color: #055160;
    border: 1px solid #b6effb;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-8px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: var(--card-bg, #f8f9fa);
    border-radius: 8px;
}

.avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid var(--border-color, #dee2e6);
}

.avatar-url-display {
    flex: 1;
}

/* Toggle Items */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.toggle-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.875rem 1rem;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.1s ease;
}

.toggle-item:hover {
    background: var(--hover-bg, #f8f9fa);
}

.toggle-switch {
    width: 2.5rem;
    height: 1.25rem;
    cursor: pointer;
}

/* Muted Channels */
.muted-channels {
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--border-color, #dee2e6);
}

.muted-channels h3 {
    margin: 0 0 1rem;
    font-size: 1.1rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    cursor: pointer;
}

.channel-item:hover {
    background: var(--hover-bg, #f8f9fa);
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid var(--border-color, #dee2e6);
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 1rem 1.25rem;
    background: var(--card-bg, #f8f9fa);
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 600;
    color: var(--text-color, #212529);
}

.panel-header:hover {
    background: var(--hover-bg, #e9ecef);
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid var(--border-color, #dee2e6);
}

/* Security Items */
.security-item {
    margin-bottom: 1.5rem;
    padding: 1.25rem;
    background: var(--card-bg, #f8f9fa);
    border-radius: 8px;
}

.twofa-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.twofa-row h3 {
    margin: 0 0 0.25rem;
    font-size: 1.05rem;
}

.status-indicator {
    font-size: 0.85rem;
    font-weight: 600;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
}

.status-enabled {
    color: #0f5132;
    background: #d1e7dd;
}

.status-disabled {
    color: #842029;
    background: #f8d7da;
}

.last-change {
    margin: 0.75rem 0 0;
    font-size: 0.85rem;
    color: var(--text-muted, #6c757d);
}

/* Sessions Table */
.sessions-section {
    margin-top: 1.5rem;
}

.sessions-section h3 {
    margin: 0 0 1rem;
    font-size: 1.1rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem 1rem;
    text-align: left;
    border-bottom: 1px solid var(--border-color, #dee2e6);
}

.sessions-table th {
    background: var(--card-bg, #f8f9fa);
    font-weight: 600;
    color: var(--label-color, #495057);
}

.sessions-table tr:hover td {
    background: var(--hover-bg, #f8f9fa);
}

.current-session-badge {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--primary-color, #0d6efd);
    background: #e7f1ff;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
}

/* Dialog */
.dialog-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    animation: fadeIn 0.15s ease;
}

.dialog {
    background: white;
    border-radius: 12px;
    padding: 1.5rem 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
}

.dialog h3 {
    margin: 0 0 0.75rem;
}

.dialog p {
    color: var(--text-muted, #6c757d);
    margin: 0 0 1.25rem;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

/* Appearance */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.375rem;
    cursor: pointer;
}

/* Live Preview */
.preview-area {
    margin-top: 2rem;
    padding: 1.5rem;
    border: 2px dashed var(--border-color, #dee2e6);
    border-radius: 8px;
    transition: all 0.2s ease;
}

.preview-area h4 {
    margin: 0 0 0.5rem;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--text-muted, #6c757d);
}

.preview-card {
    margin-top: 0.75rem;
    padding: 0.75rem 1rem;
    background: white;
    border: 1px solid var(--border-color, #dee2e6);
    border-radius: 6px;
}

.preview-card .preview-label {
    font-weight: 600;
    font-size: 0.85rem;
}

/* Theme preview variants */
.preview-theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-theme-dark .preview-card {
    background: #313244;
    border-color: #45475a;
    color: #cdd6f4;
}

.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-theme-system {
    background: #f8f9fa;
    color: #212529;
}

/* Font size preview variants */
.preview-font-small .preview-text,
.preview-font-small .preview-card {
    font-size: 0.8rem;
}

.preview-font-medium .preview-text,
.preview-font-medium .preview-card {
    font-size: 0.95rem;
}

.preview-font-large .preview-text,
.preview-font-large .preview-card {
    font-size: 1.15rem;
}

/* Compact mode preview */
.preview-compact {
    padding: 0.75rem;
}

.preview-compact .preview-card {
    padding: 0.375rem 0.625rem;
    margin-top: 0.375rem;
}

